DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.set_user_workspace_access(uuid,public.app_role,text[])'::regprocedure) INTO definition; definition:=replace(definition,'IF public.has_role(_user_id,''admin'') AND NOT public.is_company_super_admin(auth.uid()) THEN','IF public.has_role(_user_id,''admin'') AND (_role=''admin'' OR NOT public.is_company_super_admin(auth.uid())) THEN'); EXECUTE definition; END $$;